#!/bin/sh
# GENERATED by scripts/sync_workflow.py - edit the generator, not this copy.
# Copies the bundled agents, rules and gate hooks into $HOME/.claude (cloud setup script).
set -eu
HERE=$(CDPATH= cd -- "$(dirname "$0")" && pwd)
DEST="$HOME/.claude"
if [ -e "$DEST/.git" ]; then
  echo "install.sh: $DEST is a git checkout; copying nothing"
  exit 0
fi
for kind in agents rules; do
  mkdir -p "$DEST/$kind"
  for file in "$HERE/$kind"/*; do
    [ -f "$file" ] || continue
    cp "$file" "$DEST/$kind/"
    echo "installed $kind/$(basename "$file")"
  done
done
mkdir -p "$DEST/hooks"
for name in role_gate.py brief_gate.py; do
  cp "$HERE/../hooks/$name" "$DEST/hooks/"
  echo "installed hooks/$name"
done
